package erratum

import (
	"errors"
	"fmt"
)

// Use opens a resource via opener, calls Frob(input) on it, and ensures the
// resource is closed exactly once in all cases.
//
// If opener fails with a TransientError, Use keeps retrying; any other error
// is returned. If Frob panics with a FrobError, the resource's Defrob method
// is called with the FrobError's defrobTag before the resource is closed, and
// the FrobError is returned. Any other panic is recovered and returned as an
// error.
func Use(opener ResourceOpener, input string) (err error) {
	res, openErr := open(opener)
	if openErr != nil {
		return openErr
	}
	if res == nil {
		return nil
	}
	defer res.Close()

	// Registered after res.Close() so that it runs first (defers are LIFO):
	// the resource must be Defrob'ed before it is Closed.
	defer func() {
		if r := recover(); r == nil {
			return
		}
		switch p := r.(type) {
		case FrobError:
			res.Defrob(p.defrobTag)
			err = p
		case *FrobError:
			res.Defrob(p.defrobTag)
			err = p
		case error:
			err = p
		default:
			err = fmt.Errorf("panic: %v", r)
		}
	}()

	res.Frob(input)
	return nil
}

// open invokes opener, retrying while it fails with a TransientError, and
// returns either the opened resource or the first non-transient error.
func open(opener ResourceOpener) (Resource, error) {
	for {
		res, err := opener()
		if err == nil {
			return res, nil
		}
		if isTransient(err) {
			continue
		}
		return nil, err
	}
}

// isTransient reports whether err is, or wraps, a TransientError.
func isTransient(err error) bool {
	var te TransientError
	if errors.As(err, &te) {
		return true
	}
	var tpe *TransientError
	return errors.As(err, &tpe)
}

